"""
dependency_order.py

Provides plan_batches: topological-sort a dependency graph into parallel batches.
"""

from collections import deque


def _validate_dependencies(dependencies: dict[str, list[str]]) -> None:
    """Validate the structure of the dependencies input."""
    if not isinstance(dependencies, dict):
        raise TypeError(
            f"dependencies must be a dict, got {type(dependencies).__name__}"
        )
    for task, prereqs in dependencies.items():
        if not isinstance(task, str):
            raise TypeError(
                f"Task names must be strings, got {type(task).__name__!r}"
            )
        if not isinstance(prereqs, list):
            raise TypeError(
                f"Prerequisites for task {task!r} must be a list, "
                f"got {type(prereqs).__name__}"
            )
        for prereq in prereqs:
            if not isinstance(prereq, str):
                raise TypeError(
                    f"Prerequisite names must be strings, got "
                    f"{type(prereq).__name__!r} in task {task!r}"
                )


def _validate_completed(completed: set[str] | None) -> None:
    """Validate the optional completed set."""
    if completed is None:
        return
    if not isinstance(completed, set):
        raise TypeError(
            f"completed must be a set or None, got {type(completed).__name__}"
        )
    for item in completed:
        if not isinstance(item, str):
            raise TypeError(
                f"Items in completed must be strings, got {type(item).__name__!r}"
            )


def _collect_all_nodes(dependencies: dict[str, list[str]]) -> set[str]:
    """Return the union of all task names and all dependency names."""
    all_nodes: set[str] = set(dependencies.keys())
    for deps in dependencies.values():
        all_nodes.update(deps)
    return all_nodes


def _build_graph(
    dependencies: dict[str, list[str]],
    all_nodes: set[str],
) -> tuple[dict[str, int], dict[str, list[str]]]:
    """
    Build in-degree map and adjacency list (prereq -> dependents).
    Returns (in_degree, dependents).
    """
    in_degree: dict[str, int] = {node: 0 for node in all_nodes}
    dependents: dict[str, list[str]] = {node: [] for node in all_nodes}

    for task, prereqs in dependencies.items():
        for prereq in prereqs:
            dependents[prereq].append(task)
            in_degree[task] += 1

    return in_degree, dependents


def _apply_completed(
    done: set[str],
    all_nodes: set[str],
    in_degree: dict[str, int],
    dependents: dict[str, list[str]],
) -> None:
    """Reduce in-degrees of dependents of already-completed tasks (in-place)."""
    for node in done:
        if node in all_nodes:
            for dependent in dependents.get(node, []):
                in_degree[dependent] -= 1


def _kahn_batches(
    remaining_nodes: set[str],
    in_degree: dict[str, int],
    dependents: dict[str, list[str]],
    done: set[str],
) -> list[list[str]]:
    """
    Run Kahn's algorithm over remaining_nodes and return sorted batches.
    Raises ValueError if a cycle is detected.
    """
    batches: list[list[str]] = []
    queue: deque[str] = deque(
        sorted(node for node in remaining_nodes if in_degree[node] == 0)
    )
    processed = 0

    while queue:
        batch_size = len(queue)
        batch = []
        for _ in range(batch_size):
            node = queue.popleft()
            batch.append(node)
            processed += 1
            for dependent in dependents[node]:
                if dependent in done:
                    continue
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)

        batch.sort()
        batches.append(batch)

        sorted_queue = sorted(queue)
        queue.clear()
        queue.extend(sorted_queue)

    if processed != len(remaining_nodes):
        raise ValueError("Cycle detected in the dependency graph.")

    return batches


def plan_batches(
    dependencies: dict[str, list[str]],
    *,
    completed: set[str] | None = None,
) -> list[list[str]]:
    """
    Given a mapping of task -> [prerequisite tasks], return a list of batches
    where each batch is a sorted list of tasks that can run in parallel.

    Tasks that only appear as dependencies (not as keys) are included.
    Raises ValueError if the graph contains a cycle.
    Raises TypeError if inputs are of incorrect types.
    Does not mutate the input.

    Optional keyword argument:
        completed: set of tasks already done. These are excluded from the
                   returned batches but still satisfy dependencies for
                   remaining tasks.
    """
    _validate_dependencies(dependencies)
    _validate_completed(completed)

    done: set[str] = set(completed) if completed else set()

    all_nodes = _collect_all_nodes(dependencies)
    in_degree, dependents = _build_graph(dependencies, all_nodes)
    _apply_completed(done, all_nodes, in_degree, dependents)

    remaining_nodes = all_nodes - done
    return _kahn_batches(remaining_nodes, in_degree, dependents, done)

